import{_ as t,o as a,c as r,a0 as n}from"./chunks/framework.jwovEGr5.js";const p=JSON.parse('{"title":"Frensense - System Overview","description":"","frontmatter":{},"headers":[],"relativePath":"frensense-paper/00_OVERVIEW.md","filePath":"frensense-paper/00_OVERVIEW.md"}'),o={name:"frensense-paper/00_OVERVIEW.md"};function i(s,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="frensense-system-overview" tabindex="-1">Frensense - System Overview <a class="header-anchor" href="#frensense-system-overview" aria-label="Permalink to &quot;Frensense - System Overview&quot;">​</a></h1><p><strong>Version:</strong> 0.5.x<br><strong>Authors:</strong> Friehub Developers<br><strong>License:</strong> MIT</p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>Frensense is a high-performance static analysis system for Rust, TypeScript, and JavaScript that detects security vulnerabilities, architectural violations, and AI-generated code hallucinations - without hand-written rules, DSLs, or regular expressions.</p><p>The core thesis: <strong>code patterns are best expressed as pairs of concrete examples</strong> - a vulnerable function and its corrected counterpart. These pairs carry richer signal than any YAML rule because they encode structural shape, control flow, API usage, and data flow simultaneously. The engine fingerprints corpus pairs at build time and performs fast, multi-dimensional similarity search at scan time.</p><p>Findings fire only when multiple independent layers agree: structural corpus match, taint data-flow confirmation, and (optionally) cross-function consistency. This AND-gate architecture is what drives the system&#39;s low false-positive rate.</p><hr><h2 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h2><p>Existing static analysis tools fall into two paradigms:</p><table tabindex="0"><thead><tr><th>Paradigm</th><th>Examples</th><th>Weakness</th></tr></thead><tbody><tr><td><strong>Rule-based</strong></td><td>Semgrep, ESLint, Clippy</td><td>Brittle to syntactic variation; every new bug class needs a hand-written rule</td></tr><tr><td><strong>ML-based embedding</strong></td><td>CodeBERT fine-tunes, DeepBugs</td><td>Opaque predictions; high FP rate in production; expensive inference</td></tr></tbody></table><p>Frensense occupies a middle ground: the detection patterns are <em>data</em> (real code examples) rather than <em>rules</em> (DSL expressions), but the matching is <em>deterministic</em> and <em>explainable</em> (every finding comes with a per-dimension score breakdown).</p><hr><h2 id="what-it-catches" tabindex="-1">What It Catches <a class="header-anchor" href="#what-it-catches" aria-label="Permalink to &quot;What It Catches&quot;">​</a></h2><p>Three distinct categories are encoded in the corpus:</p><ol><li><p><strong>Security Vulnerabilities</strong></p><ul><li>SQL/NoSQL injection (CWE-89, CWE-943)</li><li>Server-Side Request Forgery (CWE-918)</li><li>Path Traversal (CWE-22)</li><li>Command Injection (CWE-78)</li><li>Credentials flowing to logs or HTTP responses</li></ul></li><li><p><strong>Architectural Invariants</strong></p><ul><li><code>validate_*()</code> functions with no rejection path (hollow validators)</li><li>Missing payment gates before wallet operations</li><li>Ownership checks missing from update/delete endpoints</li></ul></li><li><p><strong>LLM Hallucinations in AI-generated Code</strong></p><ul><li>Hardcoded tokens/secrets</li><li>AI-generated <code>any</code> parameters in TypeScript</li><li><code>console.log</code> in production paths</li><li><code>await</code> in synchronous contexts</li></ul></li></ol><hr><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h2><h3 id="_1-zero-rule-authoring" tabindex="-1">1. Zero Rule Authoring <a class="header-anchor" href="#_1-zero-rule-authoring" aria-label="Permalink to &quot;1. Zero Rule Authoring&quot;">​</a></h3><p>All detection derives from the <code>.frc</code> corpus bundle. Adding a new pattern means dropping two files (<code>*_positive.ts</code>, <code>*_negative.ts</code>) and running <code>--build-bundle</code>. No TOML, no YAML, no DSL.</p><h3 id="_2-multi-layer-corroboration" tabindex="-1">2. Multi-Layer Corroboration <a class="header-anchor" href="#_2-multi-layer-corroboration" aria-label="Permalink to &quot;2. Multi-Layer Corroboration&quot;">​</a></h3><p>A finding is emitted only when:</p><ul><li><strong>L1 (Corpus Match):</strong> The function&#39;s structure mathematically resembles a known vulnerable pattern.</li><li><strong>L2 (Taint Path):</strong> Tainted data demonstrably flows from a source to the implicated sink.</li><li><strong>L3 (Consistency):</strong> Sibling functions do not contradict the pattern (no double-suppression).</li></ul><h3 id="_3-deterministic-output" tabindex="-1">3. Deterministic Output <a class="header-anchor" href="#_3-deterministic-output" aria-label="Permalink to &quot;3. Deterministic Output&quot;">​</a></h3><p>Given the same source, corpus, and thresholds, the engine produces identical output on every run. No stochastic components in production paths.</p><h3 id="_4-sub-second-scan-times" tabindex="-1">4. Sub-Second Scan Times <a class="header-anchor" href="#_4-sub-second-scan-times" aria-label="Permalink to &quot;4. Sub-Second Scan Times&quot;">​</a></h3><ul><li><code>rayon</code> parallelism across files and functions</li><li>MinHash LSH pre-filtering reduces corpus matching to O(1) amortized per function</li><li>Function-level granularity avoids re-analyzing unchanged code</li></ul><h3 id="_5-extensible-without-recompilation" tabindex="-1">5. Extensible Without Recompilation <a class="header-anchor" href="#_5-extensible-without-recompilation" aria-label="Permalink to &quot;5. Extensible Without Recompilation&quot;">​</a></h3><p>New patterns compile into the <code>.frc</code> bundle. The scanner loads the bundle at startup - no code changes needed to extend detection coverage.</p><hr><h2 id="document-index" tabindex="-1">Document Index <a class="header-anchor" href="#document-index" aria-label="Permalink to &quot;Document Index&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>What It Covers</th></tr></thead><tbody><tr><td><a href="./00_OVERVIEW.html"><code>00_OVERVIEW.md</code></a></td><td>This file - abstract, goals, design principles</td></tr><tr><td><a href="./01_WORKSPACE.html"><code>01_WORKSPACE.md</code></a></td><td>Full annotated workspace and file tree</td></tr><tr><td><a href="./02_CRATE_FRC.html"><code>02_CRATE_FRC.md</code></a></td><td><code>frensense-frc</code> - binary bundle format</td></tr><tr><td><a href="./03_CRATE_LANG.html"><code>03_CRATE_LANG.md</code></a></td><td><code>frensense-lang</code> - language abstraction layer</td></tr><tr><td><a href="./04_CRATE_ENGINE.html"><code>04_CRATE_ENGINE.md</code></a></td><td><code>frensense-engine</code> - core analysis library</td></tr><tr><td><a href="./05_CRATE_BUNDLER.html"><code>05_CRATE_BUNDLER.md</code></a></td><td><code>frensense-bundler</code> - corpus compiler</td></tr><tr><td><a href="./06_CRATE_PROVIDERS.html"><code>06_CRATE_PROVIDERS.md</code></a></td><td><code>frensense-providers</code> - compiler backends</td></tr><tr><td><a href="./07_CRATE_RUNTIME.html"><code>07_CRATE_RUNTIME.md</code></a></td><td><code>frensense-runtime</code> - dynamic instrumentation</td></tr><tr><td><a href="./08_CRATE_ROOT.html"><code>08_CRATE_ROOT.md</code></a></td><td>Root crate - CLI, orchestration, MCP server</td></tr><tr><td><a href="./09_PIPELINE.html"><code>09_PIPELINE.md</code></a></td><td>End-to-end analysis pipeline</td></tr><tr><td><a href="./10_THEORY_MAP.html"><code>10_THEORY_MAP.md</code></a></td><td>CS theory mapped to every module</td></tr><tr><td><a href="./11_DATA_STRUCTURES.html"><code>11_DATA_STRUCTURES.md</code></a></td><td>Key data structures annotated</td></tr><tr><td><a href="./12_LIMITATIONS.html"><code>12_LIMITATIONS.md</code></a></td><td>Known issues and open problems</td></tr><tr><td><a href="./13_BENCHMARKS.html"><code>13_BENCHMARKS.md</code></a></td><td>Benchmark results</td></tr><tr><td><a href="./14_REFERENCES.html"><code>14_REFERENCES.md</code></a></td><td>Citations and bibliography</td></tr></tbody></table>',32)])])}const m=t(o,[["render",i]]);export{p as __pageData,m as default};
